package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.ConflictException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;

/** Save an edited person; refused (409) when someone else has saved them since the editor loaded its version.
 *  The form's grade is recorded from its from-date (blank: the sheet's today), keeping their other grades,
 *  except that a save leaving the grade in force on the sheet's today as it is, with the from-date blank,
 *  records no grade. PERSON_EDITED carries the grade in force on the sheet's today after the save, then
 *  the person's own terms when the save changed them (empty when it cleared them), then their contact when
 *  the save changed it (empty when it cleared it). */
public class SavePerson {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val PersonRequest request, ServerHttpConnection connection, PersonRepository repository,
            SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException, ConflictException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        if (request.version() == null) {
            throw new BadRequestException("version is required");
        }
        if (!repository.exists(id, pid)) {
            throw new BadRequestException("no such person");
        }
        if (repository.nameTaken(id, request.name(), pid)) {
            throw new BadRequestException("name is already in use");
        }
        if (repository.aliasClashes(id, pid)) {
            throw new BadRequestException("an alias is already in use on another sheet of the tree");
        }
        Person current = repository.find(id, pid);
        // a stale editor is told so (and shown the current values) before its contact is judged against them
        if (current.version() != request.version()) {
            throw new ConflictException("someone else has saved this person; showing their current values");
        }
        String contact = request.contact().isEmpty() ? null : request.contact();
        if (contact != null && repository.contactTaken(id, contact, pid)) {
            throw new BadRequestException("contact is already in use");
        }
        boolean regrade = !request.gradeFrom().isEmpty() || !request.grade().equals(current.grade());
        LocalDate from = request.gradeFrom().isEmpty() ? sheets.today(id) : LocalDate.parse(request.gradeFrom());
        Integer terms = request.terms().isEmpty() ? null : Integer.valueOf(request.terms());
        boolean reterm = !java.util.Objects.equals(terms, current.terms());
        boolean recontact = !java.util.Objects.equals(contact, current.contact());
        long version = request.version();
        Rollup.Snapshot before = rollup.take(id);
        boolean updated;
        try {
            updated = repository.update(id, pid, version, request.name(), terms, contact);
        } catch (DuplicateKeyException e) {
            throw new BadRequestException("name is already in use");
        }
        if (!updated) {
            throw new ConflictException("someone else has saved this person; showing their current values");
        }
        repository.tags(id, pid, request.tags());
        if (regrade) {
            repository.grade(id, pid, request.grade(), from);
        }
        Person saved = repository.find(id, pid);
        audit.record("PERSON_EDITED sheet=" + id + " by=" + by + " name=" + saved.name()
                + " grade=" + saved.grade() + (reterm ? " terms=" + (terms == null ? "" : terms) : "")
                + (recontact ? " contact=" + (contact == null ? "" : contact) : ""));
        rollup.record(id, by, before);
        person.set(saved);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the person form: a name is required (trimmed; unique on the sheet, checked when saved), the grade
 *  must be A, B or C, and a from-date is yyyy-mm-dd (blank for the sheet's today), and the terms
 *  a whole number of days from 0 to 3650 (blank for none), and the contact is trimmed and
 *  lower-cased (blank for none; unique on the sheet, checked when saved). */
public class ValidatePerson {
    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> person) throws BadRequestException {
        person.set(NewPerson.check(request));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A person on a sheet: the id the store assigned, their name and the grade (A, B or C) in force on
 *  the sheet's today, with every grade they have been given (oldest first), and the
 *  version of these values (up by one on each save), and their statements: how many have been taken,
 *  and the last one's due-total and date (both null before the first), and the date they are retired
 *  from (null when not retired; any date set means retired at once), and their holds (oldest first) and
 *  whether they have any (their open (OPEN or PENDING) claims dated within a hold, unless bound by a
 *  statement, then count in no live total), and their own terms in days (null when they have none), and their contact (null when they have none), and the sheet they were
 *  transferred from (null when they were not transferred here), and their past retirements (oldest first), and their tags (as {@link net.officefloor.hq.app.claim.Claim#tags(String)} keeps them; null when none),
 *  and their snapshots (one per SNAPSHOT line written for them, oldest first), and their statements still standing
 *  (by date, oldest first; those a merge or transfer brought over among them). */
public record Person(long id, String name, String grade, long version, long statementCount,
        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeFrom> grades,
        List<Hold> holds, Integer terms, String contact, String origin,
        List<Retirement> retirements, String tags, List<SnapshotLine> snapshots, List<StatementLine> statements) {

    public Person withGrades(List<GradeFrom> grades) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags, snapshots, statements);
    }

    public Person withHolds(List<Hold> holds) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom,
                !holds.isEmpty(), grades, holds, terms, contact, origin, retirements, tags, snapshots, statements);
    }

    public Person withRetirements(List<Retirement> retirements) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags, snapshots, statements);
    }

    public Person withSnapshots(List<SnapshotLine> snapshots) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags, snapshots, statements);
    }

    public Person withStatements(List<StatementLine> statements) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags, snapshots, statements);
    }

    public boolean retired() {
        return retiredFrom != null;
    }

    /** Their holds as they act on live totals on the sheet's today: once their retirement date is reached
     *  (the sheet's today on or after it) they are held over every date as well. */
    public List<Hold> liveHolds(String today) {
        if (retiredFrom == null || today == null || retiredFrom.compareTo(today) > 0) return holds;
        List<Hold> all = new java.util.ArrayList<>(holds);
        all.add(new Hold(null, null));
        return all;
    }
}
-- A person's own terms: the days after a claim's date that it is due by, ahead of their grade's and
-- the sheet's terms. Null when they have none.
ALTER TABLE person ADD COLUMN terms INT;
-- A person's grade is dated: each grade they are given is in force from its from-date (the first
-- one, with none, from the beginning of time) until the next one's. A person has at most one grade
-- per from-date (giving one again replaces it). person.grade keeps the grade they were first given;
-- the grade in force on a date is read from here.
CREATE TABLE person_grade (
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    grade     VARCHAR(1)   NOT NULL,
    from_date DATE
);
CREATE INDEX person_grade_person ON person_grade (person_id, from_date);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date) SELECT sheet_id, id, grade, NULL FROM person;

    /** What remains of the person's SETTLED claim with this number: its amount plus the (negative) amounts of the
     *  corrections made against it that are not VOID or DELETED, leaving out {@code exceptId} (null: none). */
    public BigDecimal remainingOf(String sheetId, long personId, String number, Long exceptId) {
        BigDecimal target = jdbc.queryForObject("SELECT amount FROM claim WHERE sheet_id = ? AND person_id = ?"
                + " AND claim_no = ? AND status = 'SETTLED' ORDER BY id LIMIT 1", BigDecimal.class, sheetId, personId, number);
        BigDecimal made = jdbc.queryForObject("SELECT COALESCE(SUM(amount), 0) FROM claim WHERE sheet_id = ? AND person_id = ?"
                + " AND corrects = ? AND status NOT IN ('VOID', 'DELETED') AND id <> ?", BigDecimal.class,
                sheetId, personId, number, exceptId == null ? -1L : exceptId);
        return target.add(made).setScale(2);
    }

    /** The due-by of a claim created now for a person with a date: the terms-th business day after the date (skipping
     *  Saturdays, Sundays and the sheet's holidays), for the person's own terms, else the terms, in force on it, of the
     *  grade the person has on it, else the sheet's terms in force on it. */
    public LocalDate dueBy(String sheetId, long personId, LocalDate date) {
        List<Integer> mine = jdbc.queryForList("SELECT terms FROM person WHERE sheet_id = ? AND id = ?", Integer.class,
                sheetId, personId);
        if (!mine.isEmpty() && mine.get(0) != null) {
            return settings.businessDaysAfter(sheetId, date, mine.get(0));
        }
        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId, personId,
                date.toString());
        return dueByOfGrade(sheetId, grade.isEmpty() ? null : grade.get(0), date);
    }

    /** The due-by of a claim created now with a date for a person of a grade (null when none) with no terms of their
     *  own: the terms-th business day after the date (skipping Saturdays, Sundays and the sheet's holidays), for the
     *  grade's terms in force on it, else the sheet's terms in force on it. */
    public LocalDate dueByOfGrade(String sheetId, String grade, LocalDate date) {
        Integer own = grade == null ? null : settings.gradeTerms(sheetId, grade, date);
